const crypto = require('crypto');

// Usa la misma variable privada que el webhook /whoami.
const botToken = typeof $env !== 'undefined' ? $env.TELEGRAM_BOT_TOKEN : '';

function result(json) {
  return [{ json }];
}

function invalid(error) {
  return result({ ok: false, valid: false, error });
}

function parseQueryString(value) {
  const fields = {};

  try {
    for (const part of String(value).split('&')) {
      const separator = part.indexOf('=');
      if (separator < 0) continue;
      const key = decodeURIComponent(part.slice(0, separator).replace(/\+/g, ' '));
      const fieldValue = decodeURIComponent(part.slice(separator + 1).replace(/\+/g, ' '));
      fields[key] = fieldValue;
    }
  } catch {
    return null;
  }

  return fields;
}

if (!botToken) throw new Error('Falta TELEGRAM_BOT_TOKEN en n8n.');

const input = $input.first()?.json ?? {};
let body = input.body ?? input;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    return invalid('invalid_json');
  }
}

const initData = typeof body.initData === 'string' ? body.initData.trim() : '';
const itemId = typeof body.item_id === 'string' ? body.item_id.trim() : '';
if (!initData) return invalid('telegram_init_data_missing');
if (!itemId || itemId.length > 120) return invalid('item_id_invalid');

const fields = parseQueryString(initData);
if (!fields) return invalid('telegram_init_data_malformed');

const receivedHash = fields.hash ?? '';
const authDate = Number(fields.auth_date);
if (!/^[a-f0-9]{64}$/i.test(receivedHash) || !Number.isInteger(authDate)) {
  return invalid('telegram_init_data_invalid');
}

const now = Math.floor(Date.now() / 1000);
if (authDate > now + 60 || now - authDate > 600) return invalid('telegram_init_data_expired');

const dataCheckString = Object.keys(fields)
  .filter((key) => key !== 'hash')
  .sort()
  .map((key) => `${key}=${fields[key]}`)
  .join('\n');

const secretKey = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
const expectedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');
const received = Buffer.from(receivedHash, 'hex');
const expected = Buffer.from(expectedHash, 'hex');
if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
  return invalid('telegram_identity_invalid');
}

let user;
try {
  user = JSON.parse(fields.user ?? '{}');
} catch {
  return invalid('telegram_user_invalid');
}

if (!user || !Number.isSafeInteger(user.id)) return invalid('telegram_user_invalid');

return result({
  ok: true,
  valid: true,
  item_id: itemId,
  telegram_id: String(user.id),
});

const auth = $('Validate Telegram initData').first()?.json ?? {};
const rows = $input.all();

if (auth.valid !== true) {
  return [{ json: auth }];
}

const found = rows
  .map(({ json }) => {
    const fields = json.fields ?? json;
    return { json, fields };
  })
  .find(({ fields }) => String(fields['item-id'] ?? '') === String(auth.item_id));

if (!found) {
  return [{ json: { ok: false, valid: false, error: 'item_not_found' } }];
}

const fields = found.fields;
const ownerTelegramId = String(fields.owner_telegram_id ?? '');
if (!ownerTelegramId || ownerTelegramId !== String(auth.telegram_id)) {
  return [{ json: { ok: false, valid: false, error: 'not_owner' } }];
}

if (fields.status === 'completed') {
  return [{ json: { ok: false, valid: false, error: 'item_already_completed' } }];
}

if (fields.status !== 'available') {
  return [{ json: { ok: false, valid: false, error: 'item_not_available' } }];
}

const rowId = fields.Id ?? found.json.Id ?? found.json.id ?? null;
if (rowId === null || rowId === undefined || rowId === '') {
  return [{ json: { ok: false, valid: false, error: 'nocodb_row_id_missing' } }];
}

return [{
  json: {
    ok: true,
    valid: true,
    Id: rowId,
    item_id: auth.item_id,
    completed_at: new Date().toISOString(),
    title: fields.title ?? '',
  },
}];

const input = $('Verify owner and item').first()?.json ?? {};
return [{
  json: {
    ok: true,
    item_id: input.item_id ?? '',
    title: input.title ?? '',
    status: 'completed',
    completed_at: input.completed_at ?? new Date().toISOString(),
    message: 'Marcado como entregado',
  },
}];
